import { ValueObject } from '@/shared/domain'
import { UuidUtil } from '@/shared/utils'
import { NotificationValidationException } from '../exceptions/notification-validation.exception'

/** Value-object state for a notification identifier. */
interface NotificationIdProps {
  readonly value: string
}

/**
 * Identifies a Notification aggregate using a UUIDv7 generated by Orbit.
 *
 * - Existing values are validated before reconstitution.
 */
export class NotificationId extends ValueObject<NotificationIdProps> {
  private constructor(props: NotificationIdProps) {
    super(props)
  }

  /** Creates a new identifier or validates an existing identifier. */
  static create(value: string = UuidUtil.generate()): NotificationId {
    if (!UuidUtil.isValid(value)) {
      throw new NotificationValidationException('Invalid notification ID')
    }

    return new NotificationId({ value })
  }

  get value(): string {
    return this.props.value
  }
}
